package com.pp.shaderlod.optimization.makeupshadow;import java.util.*;import java.security.*;import com.google.gson.*;public final class MakeUpShadowPins{private static final String KIND=check();private MakeUpShadowPins(){}public static boolean exact(){return KIND!=null;}public static String kind(){return KIND;}private static String check(){try(var in=MakeUpShadowPins.class.getResourceAsStream("/assets/shaderlod/adapters/qualification/makeup-shadow-api.json")){if(in==null)return null;byte[] all=in.readAllBytes();if(!HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(all)).equals("d415645c5d5a0bbd7cde2ce3a51b8e02de7c1701a2d5816e2df4126d80313bf0"))return null;for(var row:JsonParser.parseString(new String(all,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonArray()){boolean ok=true;for(var e:row.getAsJsonObject().getAsJsonObject("classes").entrySet())try(var b=MakeUpShadowPins.class.getClassLoader().getResourceAsStream(e.getKey())){if(b==null||!HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b.readAllBytes())).equals(e.getValue().getAsString())){ok=false;break;}}if(ok)return row.getAsJsonObject().get("kind").getAsString();}}catch(Exception|LinkageError e){}return null;}}